parameters.functionCode:
// Verify HMAC signature
const crypto = require("crypto");
const signatureHeader = $json["x-signature"];
const payload = JSON.stringify($json);

if (!signatureHeader) {
  // No signature - still process but mark as unverified
  $return = [{ event: $json.event, lead: $json.lead, signatureValid: false }];
  return;
}

// Parse signature format: timestamp=signature
const parts = signatureHeader.split("=");
const timestamp = parseInt(parts[0], 10);
const providedSignature = parts[1] || signatureHeader;

// Check timestamp (5 minutes replay prevention)
const now = Math.floor(Date.now() / 1000);
if (isNaN(timestamp) || Math.abs(now - timestamp) > 300) {
  $return = [{ event: $json.event, lead: $json.lead, signatureValid: false, error: "Invalid timestamp" }];
  return;
}

// Verify HMAC-SHA256
const secret = "tu-secreto-aqui";
const hmac = crypto.createHmac("sha256", secret);
hmac.update(payload);
const calculatedSignature = hmac.digest("hex");

const signatureValid = crypto.timingSafeEqual(
  Buffer.from(calculatedSignature, "hex"),
  Buffer.from(providedSignature, "hex")
);

$return = [{ event: $json.event, lead: $json.lead, signatureValid }];

